-- ========================================================
-- SKILLORA AI — COMPLETE SUPABASE DATABASE SETUP & SEED
-- Run this in your Supabase SQL Editor:
-- https://supabase.com/dashboard/project/_/sql
-- ========================================================

-- 1. Create Prompts Table
CREATE TABLE IF NOT EXISTS public.prompts (
    id BIGINT PRIMARY KEY,
    "numericId" INTEGER,
    type TEXT NOT NULL DEFAULT 'video',
    title TEXT NOT NULL,
    slug TEXT,
    category TEXT,
    "categoryId" TEXT,
    access TEXT NOT NULL DEFAULT 'free',
    "isTrending" BOOLEAN DEFAULT false,
    "aspectRatio" TEXT DEFAULT '9:16',
    model TEXT,
    "publishedLabel" TEXT,
    "coverImage" TEXT,
    tags JSONB DEFAULT '[]'::jsonb,
    description TEXT,
    "promptText" TEXT NOT NULL,
    "negativePrompt" TEXT,
    settings JSONB DEFAULT '{}'::jsonb,
    storyboards JSONB DEFAULT '[]'::jsonb,
    "workflowGuide" JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Create Pricing Plans Table
CREATE TABLE IF NOT EXISTS public.pricing_plans (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    badge TEXT,
    subtitle TEXT,
    audience TEXT,
    title TEXT,
    description TEXT,
    "originalPrice" TEXT,
    price TEXT NOT NULL,
    billing TEXT,
    "saveText" TEXT,
    features JSONB DEFAULT '[]'::jsonb,
    cta TEXT,
    popular BOOLEAN DEFAULT false,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. Create Site Config Table
CREATE TABLE IF NOT EXISTS public.site_config (
    id TEXT PRIMARY KEY DEFAULT 'default',
    "brandName" TEXT DEFAULT 'Skillora AI',
    tagline TEXT DEFAULT 'LEARN. EARN. GROW.',
    phone TEXT DEFAULT '+92 316 1056008',
    email TEXT DEFAULT 'support@skillora.ai',
    "supportHours" TEXT DEFAULT 'Mon - Sun: 24/7 Creator Support',
    "whatsAppNumber" TEXT DEFAULT '923161056008',
    "adminPin" TEXT DEFAULT 'skillora2026',
    "heroSubtitle" TEXT DEFAULT 'WELCOME TO SKILLORA AI',
    "heroTitle" TEXT DEFAULT 'QUALITY AI PROMPTS, BUILT FOR VIRAL CREATORS',
    "heroDescription" TEXT DEFAULT 'OUR TEAM OF PROMPT ENGINEERS WILL HELP YOU TURN YOUR CREATIVE IDEAS INTO REALITY.',
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 4. Enable Row Level Security (RLS) & Public Policies
ALTER TABLE public.prompts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pricing_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.site_config ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read access to prompts" ON public.prompts;
DROP POLICY IF EXISTS "Allow public read access to pricing_plans" ON public.pricing_plans;
DROP POLICY IF EXISTS "Allow public read access to site_config" ON public.site_config;
DROP POLICY IF EXISTS "Allow full access to prompts" ON public.prompts;
DROP POLICY IF EXISTS "Allow full access to pricing_plans" ON public.pricing_plans;
DROP POLICY IF EXISTS "Allow full access to site_config" ON public.site_config;

CREATE POLICY "Allow public read access to prompts" ON public.prompts FOR SELECT USING (true);
CREATE POLICY "Allow public read access to pricing_plans" ON public.pricing_plans FOR SELECT USING (true);
CREATE POLICY "Allow public read access to site_config" ON public.site_config FOR SELECT USING (true);

CREATE POLICY "Allow full access to prompts" ON public.prompts FOR ALL USING (true);
CREATE POLICY "Allow full access to pricing_plans" ON public.pricing_plans FOR ALL USING (true);
CREATE POLICY "Allow full access to site_config" ON public.site_config FOR ALL USING (true);

