VALUES (2001010, 1010, 'image', 'Himalayan Elderly Master Woodcarver 85mm Portrait', 'himalayan-master-woodcarver-portrait', 'Portraits & People', 'portrait', 'free', true, '4:5', 'Midjourney v6.1 / Flux.1 Pro', '21 Oct 2026', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=800&q=80', '["Portrait","Photorealism","Himalayas","Craftsman","85mm"]'::jsonb, 'Hyper-detailed National Geographic portrait of an 80-year-old Tibetan woodcarver with weathered wrinkles and silver beard.', 'An intimate close-up portrait of an 82-year-old Tibetan master woodcarver in Ladakh. Deep dignified facial wrinkles, wise laughing hazel eyes, silver braided beard, wearing weathered yak wool tunic dusted with fine cedar shavings. Holding an antique steel carving gouge. Soft natural window sidelight inside a rustic wooden workshop, cedar wood chips scattered on table, shallow depth of field, shot on Sony A7R V with 85mm f/1.2 GM lens, photorealistic skin pores, National Geographic cover masterwork --ar 4:5 --v 6.1 --style raw', 'plastic skin, airbrushed, cartoon, oversaturated, deformed hands, extra fingers', '{"aspectRatio":"4:5 (Instagram / Fine Art Print)","recommendedModel":"Midjourney v6.1 (--style raw) or Flux.1 Pro","guidanceScale":"3.5 (Flux) / Stylize 250 (Midjourney)","sampler":"Euler / DPM++ 2M Karras"}'::jsonb, '[]'::jsonb, '[]'::jsonb)
