VALUES (2001080, 1080, 'image', 'Michelin-Star Truffle Wagyu Steak Plating', 'michelin-truffle-wagyu-steak', 'Commercial & Ads', 'commercial', 'free', false, '4:5', 'Midjourney v6.1', '14 Oct 2026', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Food Photography","Gourmet","Wagyu","Michelin","Editorial"]'::jsonb, 'Gastronomy food editorial photograph of seared A5 Miyazaki Wagyu beef steak with shaved black Perigord truffles.', 'Michelin 3-star culinary food editorial photograph, perfectly seared rare A5 Miyazaki Wagyu beef medallion sliced to reveal marbling, garnished with fresh shaved black Perigord winter truffles, glossy bone marrow demi-glace drizzle, micro-greens, coarse smoked sea salt crystals. Plated on a dark hand-thrown textured slate dish, moody restaurant spotlighting, shallow depth of field, Bon Appétit magazine cover quality, shot on Hasselblad H6D-100c --ar 4:5 --style raw', 'burnt meat, messy plate, greasy, unappetizing, flat lighting', '{"aspectRatio":"4:5","recommendedModel":"Midjourney v6.1 (--style raw)","guidanceScale":"Stylize 150","sampler":"Default"}'::jsonb, '[]'::jsonb, '[]'::jsonb)
