VALUES (2001090, 1090, 'image', 'Retro 1984 Synthwave DeLorean at Sunset Grid', 'retro-synthwave-delorean-sunset', 'Sci-Fi & Cyberpunk', 'scifi', 'free', true, '16:9', 'Flux.1 Dev / Midjourney', '13 Oct 2026', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?auto=format&fit=crop&w=800&q=80', '["Outrun","Synthwave","DeLorean","Retro","Neon Grid"]'::jsonb, 'Brushed stainless steel DeLorean parked on an infinite glowing digital grid road facing an enormous low-poly magenta sunset.', 'Classic 1980s synthwave aesthetic, brushed stainless steel DeLorean DMC-12 sports car rear three-quarter view parked on reflective wet purple grid highway. Enormous glowing striped neon sunset on horizon in cadmium orange and magenta, wireframe mountains, cyan grid lines stretching into vanishing point, nostalgic VHS film grain texture, Outrun album cover artwork, 8k resolution --ar 16:9', 'modern supercar, daylight, muddy colors, low resolution, bad car shape', '{"aspectRatio":"16:9","recommendedModel":"Flux.1 Dev","guidanceScale":"4.0","sampler":"Euler A"}'::jsonb, '[]'::jsonb, '[]'::jsonb)
