VALUES (2001120, 1120, 'image', 'Water Droplet Refracting Milky Way Galaxy Macro', 'water-droplet-milky-way-macro', 'Science & 3D', 'science', 'free', true, '1:1', 'Flux.1 Pro / Midjourney', '10 Oct 2026', 'https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?auto=format&fit=crop&w=800&q=80', '["Macro","Water Drop","Milky Way","Cosmic","Physics"]'::jsonb, 'A single crystal-clear water droplet suspended on a dandelion seed, acting as a natural optical lens refracting the spiral galaxy.', 'Extreme macro photograph of a single perfect spherical water droplet suspended from the tip of a fine dandelion pappus seed. Inside the droplet, the entire spiral Milky Way galaxy is inverted and crisply refracted in astronomical detail with billions of stars and magenta nebula dust. Deep velvety black space background, soft rim lighting on water meniscus, Canon MP-E 65mm 5:1 macro lens, focus stacked 50 shots, ultra-sharp scientific photography --ar 1:1 --style raw', 'blurry droplet, dirty water, noisy background, artificial glitter, lowres', '{"aspectRatio":"1:1","recommendedModel":"Flux.1 Pro / Midjourney v6.1","guidanceScale":"3.0","sampler":"Euler"}'::jsonb, '[]'::jsonb, '[]'::jsonb)
