VALUES (2001140, 1140, 'image', 'Cyberpunk Ramen Street Food Night Vendor', 'cyberpunk-ramen-street-vendor', 'Sci-Fi & Cyberpunk', 'scifi', 'free', true, '4:5', 'Flux.1 Dev / Midjourney', '8 Oct 2026', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Cyberpunk","Ramen","Street Food","Neon","Cinematic"]'::jsonb, 'An atmospheric night photography shot of a crowded cyber street ramen cart with glowing neon signs and piping hot broth steam.', 'Night street photography of a tiny open-air ramen stall in futuristic Neo-Seoul. A chef with cybernetic mechanical forearms serving a steaming bowl of spicy tonkotsu ramen with soft-boiled egg and nori, thick aromatic steam illuminated by vertical holographic Korean signage in red and turquoise, rain puddle reflections on wet asphalt, shot on 35mm f/1.4 lens, cinematic mood --ar 4:5', 'blurry, messy face, oversaturated cartoon, flat lighting, digital noise', '{"aspectRatio":"4:5","recommendedModel":"Flux.1 Dev","guidanceScale":"3.5","sampler":"DPM++ 2M"}'::jsonb, '[]'::jsonb, '[]'::jsonb)
