VALUES (2001150, 1150, 'image', 'Moroccan Oasis Riad Courtyard & Turquoise Pool', 'moroccan-oasis-riad-courtyard', 'Architecture & Spaces', 'architecture', 'free', false, '4:5', 'Midjourney v6.1', '7 Oct 2026', 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=800&q=80', '["Morocco","Riad","Architecture","Interior","Luxury"]'::jsonb, 'A breathtaking Marrakech palace courtyard with emerald zellige mosaic tiles, banana palms, and crystal turquoise plunge pool.', 'Architectural Digest photography, a secluded luxury traditional riad courtyard in Marrakech at golden hour. Hand-carved plaster arches, intricate cobalt blue and emerald green zellige mosaic tilework, tranquil turquoise reflection pool scattered with floating fresh jasmine petals, giant banana palm trees, sunbeams streaming down central skylight, interior design masterpiece, shot on Leica SL2 --ar 4:5 --style raw', 'crooked walls, blurry tiles, distorted arches, messy pool, cheap plastic', '{"aspectRatio":"4:5","recommendedModel":"Midjourney v6.1","guidanceScale":"Stylize 200","sampler":"Default"}'::jsonb, '[]'::jsonb, '[]'::jsonb)
