VALUES (2001160, 1160, 'image', 'Minimalist Matte Black Wireless Audio Studio Shot', 'minimalist-matte-black-headphones', 'Commercial & Ads', 'commercial', 'free', true, '1:1', 'Flux.1 Pro / Midjourney', '6 Oct 2026', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=80', '["Product Design","Commercial","Audio","Headphones","Minimalism"]'::jsonb, 'Clean Apple/Bang & Olufsen style commercial product shot of luxury matte black wireless over-ear headphones floating against stone.', 'Commercial product advertising photograph, sleek ultra-premium matte black over-ear wireless headphones with brushed titanium earcups and soft Italian memory foam leather pads levitating above a dark textured slate plinth. Subtle three-point softbox studio rim lighting accentuating clean industrial curves, pure commercial aesthetic, Hasselblad H6D-100c, crystal clarity --ar 1:1 --style raw', 'cheap plastic, scratches, dust, fingerprints, messy wire, lowres', '{"aspectRatio":"1:1","recommendedModel":"Flux.1 Pro","guidanceScale":"3.0","sampler":"Euler"}'::jsonb, '[]'::jsonb, '[]'::jsonb)
